    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    frames = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue

            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            cellset = set(cells)

            if r1 <= r0 + 1 or c1 <= c0 + 1:
                continue
            if not (all((r0, x) in cellset and (r1, x) in cellset
                        for x in range(c0, c1 + 1)) and
                    all((y, c0) in cellset and (y, c1) in cellset
                        for y in range(r0, r1 + 1))):
                continue

            motif = {(y-r0-1, x-c0-1) for y, x in cells
                     if r0 < y < r1 and c0 < x < c1}
            frames.append({
                "color": color, "box": (r0, r1, c0, c1),
                "size": (r1-r0-1, c1-c0-1),
                "motif": motif, "cells": cells
            })

    sources = [f for f in frames if f["motif"]]
    if not sources:
        return out
    source = max(sources, key=lambda f: len(f["motif"]))
    sh, sw = source["size"]

    for frame in frames:
        if frame is source:
            continue
        r0, r1, c0, c1 = frame["box"]
        if frame["size"] == (sh, sw) and not frame["motif"]:
            for dy, dx in source["motif"]:
                out[r0 + 1 + dy][c0 + 1 + dx] = frame["color"]
        elif frame["size"] != (sh, sw) and not frame["motif"]:
            for y, x in frame["cells"]:
                out[y][x] = 0

    return out
